def balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    in_string = False
    i = 0
    while i < len(s):
        ch = s[i]
        if in_string:
            if ch == '\\':
                i += 2
                continue
            if ch == '"':
                in_string = False
        else:
            if ch == '"':
                in_string = True
            elif ch in '([{':
                stack.append(ch)
            elif ch in ')]}':
                if not stack or stack.pop() != pairs[ch]:
                    return False
        i += 1
    return not in_string and not stack
